const menu=document.querySelector('.menu'),nav=document.querySelector('#nav');
function closeMenu(){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');nav.classList.remove('open');nav.querySelectorAll('details[open]').forEach(d=>d.open=false)}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('open',open)});
nav.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){closeMenu();menu.focus()}});
const content={play:{kicker:'YOUR NEXT ROUND STARTS HERE',title:'Same friendly rivalry.<br>New home course.',description:'Bring your foursome together for a round on GSPro. All the competition, all the laughs, without checking the weather.',link:'Find your tee time',url:'https://avidgolf.golfbooking.ca/bookingsheet.php'},practise:{kicker:'MAKE EVERY SESSION COUNT',title:'A little practice.<br>A different game.',description:'Find your rhythm, work on your swing, and put the numbers to work. Want a second set of eyes? Explore coaching at Avid.',link:'Explore coaching',url:'coaching-clinics.html'},unwind:{kicker:'GOOD COMPANY IS PART OF THE GAME',title:'The round ends.<br>The good times don’t.',description:'Grab a drink, catch up with friends, and settle into the lounge. There’s always a reason to stay a little longer.',link:'Plan your visit',url:'#visit'}};
const tabs=[...document.querySelectorAll('[role=tab]')];function activateTab(tab,focus=false){tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===tab));t.tabIndex=t===tab?0:-1});const c=content[tab.dataset.tab];document.querySelector('#tab-kicker').textContent=c.kicker;document.querySelector('#tab-title').innerHTML=c.title;document.querySelector('#tab-description').textContent=c.description;const link=document.querySelector('#tab-link');link.innerHTML=c.link+' <span aria-hidden="true">↗</span>';link.href=c.url;link.target=c.url.startsWith('https:')?'_blank':'_self';document.querySelector('#experience-panel').setAttribute('aria-labelledby',tab.id);if(focus)tab.focus()}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>activateTab(tab));tab.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();activateTab(tabs[n],true)}})});
const reduce=matchMedia('(prefers-reduced-motion: reduce)');const motion=document.querySelector('#motion');let paused=reduce.matches;try{const saved=sessionStorage.getItem('avid-motion-paused');if(saved!==null)paused=saved==='true'}catch{}function setMotion(){document.body.classList.toggle('motion-paused',paused);document.documentElement.style.scrollBehavior=paused?'auto':'';motion.setAttribute('aria-pressed',String(paused));motion.textContent=paused?'Enable motion':'Pause motion'}setMotion();motion.addEventListener('click',()=>{paused=!paused;try{sessionStorage.setItem('avid-motion-paused',String(paused))}catch{}setMotion()});reduce.addEventListener('change',e=>{paused=e.matches;setMotion()});
if('IntersectionObserver' in window&&!reduce.matches){const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.remove('pending');observer.unobserve(e.target)}})},{threshold:.08});document.querySelectorAll('.intro-grid,.experience-feature,.tech-grid,.more-heading,.more-grid,.questions,.visit-main').forEach(el=>{el.classList.add('reveal','pending');observer.observe(el)})}

// Keep mobile and desktop menu state in sync.
const header=document.querySelector('.header');
document.addEventListener('click',e=>{if(nav.classList.contains('open')&&!header.contains(e.target))closeMenu()});
header.addEventListener('focusout',()=>{setTimeout(()=>{if(!header.contains(document.activeElement))closeMenu()},0)});
matchMedia('(max-width:1050px)').addEventListener('change',closeMenu);
